-- Preserve existing network coverage, jobs, needs and slot scoping.
do $patch$ declare body text;begin
 body:=pg_get_functiondef('public.nexus_city_life_metrics(uuid,integer,text)'::regprocedure);
 if position(' return m||jsonb_build_object(' in body)=0 then raise exception 'Review life metrics before applying';end if;
 body:=replace(body,' return m||jsonb_build_object(', $new$ m:=m||jsonb_build_object('city_level',c.city_level);
 return m||jsonb_build_object($new$);
 execute body;
end $patch$;
-- Level unlocks are authoritative as well as visible in the interface.
do $patch$ declare body text;needle text;begin
 body:=pg_get_functiondef('public.nexus_city_life_action(uuid,text,text,uuid)'::regprocedure);
 needle:=$old$if event->>'status'<>'available' then raise exception 'Termine le rendez-vous précédent';end if;$old$;
 if position(needle in body)=0 then raise exception 'Review life action before applying';end if;
 body:=replace(body,needle,needle||$new$
   if coalesce((view->>'city_level')::integer,1)<coalesce((event->>'level')::integer,1) then raise exception 'Niveau municipal insuffisant pour ce dossier';end if;$new$);
 execute body;
end $patch$;
